    skRectangle(prof, "r", { "firstCorner" : vector(-3, 0) * millimeter, "secondCorner" : vector(3, 6) * millimeter });
    skSolve(prof);
    sweep(context, id + "sweep1", { "profiles" : qSketchRegion(id + "prof"), "path" : qOwnedByBody(qBodyType(qCreatedBy(id + "path", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "bodyType" : ExtendedToolBodyType.SOLID, "operationType" : NewBodyOperationType.NEW, "profileControl" : ProfileControlMode.LOCK_FACES, "lockFaces" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(50, 30, 0) * millimeter) });
