    cutlist(context, id + "cutlist1", { "selectAllFrames" : false, "frames" : qBodyType(qCreatedBy(id + "frame1", EntityType.BODY), BodyType.SOLID), "columnOverrides" : [{ "isFirst" : true, "overrideAllFrames" : false, "overrideFrames" : qClosestTo(qBodyType(qCreatedBy(id + "frame1", EntityType.BODY), BodyType.SOLID), vector(50, 0, 0) * millimeter), "column" : "Description", "value" : "Long rail" }] });
