// external-thread: a 3/8-16 thread 12 mm down two shafts at once
export function c006(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 4.7625 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    const pinSketch = newSketchOnPlane(context, id + "pinSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(pinSketch, "circle1", { "center" : vector(20, 0) * millimeter, "radius" : 4.7625 * millimeter });
    skSolve(pinSketch);
    extrude(context, id + "pin", { "entities" : qSketchRegion(id + "pinSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
